package com.gameaggregator.clientservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.clientservice.application.ClientService;import com.gameaggregator.clientservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/clients") public class ClientController{final ClientService s;public ClientController(ClientService s){this.s=s;}@PostMapping("/organizations") ApiResponse<ClientOrganization> org(@Valid @RequestBody ClientDtos.Organization r){return ApiResponse.success(s.organization(r));}@GetMapping("/organizations") ApiResponse<List<ClientOrganization>> orgs(){return ApiResponse.success(s.organizations());}@PostMapping("/organizations/{id}/applications") ApiResponse<ClientApplication> app(@PathVariable UUID id,@Valid @RequestBody ClientDtos.Application r){return ApiResponse.success(s.application(id,r));}@PostMapping("/applications/{id}/environments") ApiResponse<ClientEnvironment> env(@PathVariable UUID id,@Valid @RequestBody ClientDtos.Environment r){return ApiResponse.success(s.environment(id,r));}@PostMapping("/environments/{id}/allowlist") ApiResponse<AllowlistEntry> allow(@PathVariable UUID id,@Valid @RequestBody ClientDtos.Allowlist r){return ApiResponse.success(s.allow(id,r));}@PatchMapping("/applications/{id}/integration-status") ApiResponse<ClientApplication> integration(@PathVariable UUID id,@Valid @RequestBody ClientDtos.Integration r){return ApiResponse.success(s.integration(id,r));}@PostMapping("/applications/{id}/entitlements") ApiResponse<ClientEntitlement> entitlement(@PathVariable UUID id,@Valid @RequestBody ClientDtos.Entitlement r){return ApiResponse.success(s.entitlement(id,r));}}
